import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.CRbjHCyB.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"clice/guide/configuration.md","filePath":"en/clice/guide/configuration.md"}'),i={name:"clice/guide/configuration.md"};function s(d,e,c,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>clice reads configuration from <code>clice.toml</code> in the workspace root, or from <code>.clice/config.toml</code> if the former does not exist. Configuration can also be passed via LSP <code>initializationOptions</code> (JSON format); values from <code>initializationOptions</code> override the config file, and defaults fill in whatever remains unset after the merge.</p><p>Configuration is read once at server startup. Changing it — either file — requires restarting the server; there is no hot reload.</p><h2 id="variable-substitution" tabindex="-1">Variable Substitution <a class="header-anchor" href="#variable-substitution" aria-label="Permalink to &quot;Variable Substitution&quot;">​</a></h2><p>The following variable is supported in string values:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>${workspace}</code></td><td>The workspace directory provided by the client</td></tr></tbody></table><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><h3 id="project-clang-tidy" tabindex="-1"><code>project.clang_tidy</code> <a class="header-anchor" href="#project-clang-tidy" aria-label="Permalink to &quot;`project.clang_tidy`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Enable experimental clang-tidy diagnostics. <strong>Not yet wired</strong> — the option is parsed but has no effect currently.</p><h3 id="project-max-active-file" tabindex="-1"><code>project.max_active_file</code> <a class="header-anchor" href="#project-max-active-file" aria-label="Permalink to &quot;`project.max_active_file`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>int</code></td><td><code>8</code></td></tr></tbody></table><p>Maximum number of active files to keep in memory. <strong>Not yet wired</strong> — the option is parsed but the worker still uses a hardcoded limit.</p><h3 id="project-cache-dir" tabindex="-1"><code>project.cache_dir</code> <a class="header-anchor" href="#project-cache-dir" aria-label="Permalink to &quot;`project.cache_dir`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>$XDG_CACHE_HOME/clice/&lt;workspace&gt;-&lt;hash&gt;</code> or <code>${workspace}/.clice</code></td></tr></tbody></table><p>Directory for the unified on-disk cache (PCH, PCM, and index artifacts all live here). The default uses XDG_CACHE_HOME (or <code>~/.cache</code>) with a per-workspace subdirectory named after the workspace directory plus a short hash, e.g. <code>~/.cache/clice/myproject-1a2b3c4d</code>. Falls back to <code>${workspace}/.clice</code> if the XDG directory cannot be created. The resolved paths are printed at startup in the effective configuration dump (visible in your editor&#39;s clice output panel).</p><h3 id="project-logging-dir" tabindex="-1"><code>project.logging_dir</code> <a class="header-anchor" href="#project-logging-dir" aria-label="Permalink to &quot;`project.logging_dir`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>${cache_dir}/logs</code></td></tr></tbody></table><p>Directory for log files. Each server session logs into its own timestamped subdirectory; the startup log line <code>Session log directory:</code> shows the exact path.</p><h3 id="project-compile-commands-paths" tabindex="-1"><code>project.compile_commands_paths</code> <a class="header-anchor" href="#project-compile-commands-paths" aria-label="Permalink to &quot;`project.compile_commands_paths`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Paths to search for <code>compile_commands.json</code> files. Entries can be direct file paths or directories (clice looks for <code>compile_commands.json</code> inside). When empty (the default), clice searches the workspace root and then each of its immediate subdirectories, using the first <code>compile_commands.json</code> it finds.</p><h3 id="project-enable-indexing" tabindex="-1"><code>project.enable_indexing</code> <a class="header-anchor" href="#project-enable-indexing" aria-label="Permalink to &quot;`project.enable_indexing`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Enable background indexing for cross-TU features (find references, workspace symbols, etc.).</p><h3 id="project-idle-timeout-ms" tabindex="-1"><code>project.idle_timeout_ms</code> <a class="header-anchor" href="#project-idle-timeout-ms" aria-label="Permalink to &quot;`project.idle_timeout_ms`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>int</code></td><td><code>3000</code></td></tr></tbody></table><p>Idle time (milliseconds) before starting background indexing after the last edit.</p><h3 id="project-stateful-worker-count" tabindex="-1"><code>project.stateful_worker_count</code> <a class="header-anchor" href="#project-stateful-worker-count" aria-label="Permalink to &quot;`project.stateful_worker_count`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>2</code></td></tr></tbody></table><p>Number of stateful worker processes. These hold ASTs in memory and serve queries (hover, semantic tokens, etc.).</p><h3 id="project-stateless-worker-count" tabindex="-1"><code>project.stateless_worker_count</code> <a class="header-anchor" href="#project-stateless-worker-count" aria-label="Permalink to &quot;`project.stateless_worker_count`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>max(cores/2, 2)</code></td></tr></tbody></table><p>Number of stateless worker processes spawned at startup. These handle ephemeral tasks (PCH/PCM builds, completion, signature help).</p><h3 id="project-min-stateless-worker-count" tabindex="-1"><code>project.min_stateless_worker_count</code> <a class="header-anchor" href="#project-min-stateless-worker-count" aria-label="Permalink to &quot;`project.min_stateless_worker_count`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>0</code> (auto)</td></tr></tbody></table><p>Lower bound for dynamic scale-down of stateless workers. <code>0</code> resolves to an automatic minimum.</p><h3 id="project-max-stateless-worker-count" tabindex="-1"><code>project.max_stateless_worker_count</code> <a class="header-anchor" href="#project-max-stateless-worker-count" aria-label="Permalink to &quot;`project.max_stateless_worker_count`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>0</code> (auto)</td></tr></tbody></table><p>Upper bound for dynamic scale-up of stateless workers. <code>0</code> resolves to the CPU core count.</p><h3 id="project-worker-memory-limit" tabindex="-1"><code>project.worker_memory_limit</code> <a class="header-anchor" href="#project-worker-memory-limit" aria-label="Permalink to &quot;`project.worker_memory_limit`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint64</code></td><td><code>4294967296</code> (4 GB)</td></tr></tbody></table><p>Per-worker memory limit in bytes. <strong>Not yet enforced</strong> — the option is parsed but memory-based eviction/restart is not implemented yet.</p><h2 id="tracker" tabindex="-1">Tracker <a class="header-anchor" href="#tracker" aria-label="Permalink to &quot;Tracker&quot;">​</a></h2><p>The file tracker polls for changes that happen outside the editor (a <code>git checkout</code>, a regenerated <code>compile_commands.json</code>, code generators writing headers) so the server picks them up without a restart. Setting an interval to <code>0</code> disables that polling loop.</p><h3 id="tracker-cdb-poll-seconds" tabindex="-1"><code>tracker.cdb_poll_seconds</code> <a class="header-anchor" href="#tracker-cdb-poll-seconds" aria-label="Permalink to &quot;`tracker.cdb_poll_seconds`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>3</code></td></tr></tbody></table><p>Interval for re-checking the compilation database file.</p><h3 id="tracker-workspace-poll-seconds" tabindex="-1"><code>tracker.workspace_poll_seconds</code> <a class="header-anchor" href="#tracker-workspace-poll-seconds" aria-label="Permalink to &quot;`tracker.workspace_poll_seconds`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>30</code></td></tr></tbody></table><p>Interval for sweeping workspace files for on-disk changes.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p><code>[[rules]]</code> is an array of rule objects. Rules are matched in declaration order — later rules override earlier ones.</p><h3 id="rules-patterns" tabindex="-1"><code>[rules].patterns</code> <a class="header-anchor" href="#rules-patterns" aria-label="Permalink to &quot;`[rules].patterns`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Glob patterns for matching file paths:</p><ul><li><code>*</code> — matches one or more characters in a path segment</li><li><code>?</code> — matches a single character in a path segment</li><li><code>**</code> — matches any number of path segments, including zero</li><li><code>{}</code> — groups conditions (e.g., <code>**/*.{h,cpp}</code>)</li><li><code>[]</code> — character range (e.g., <code>example.[0-9]</code>)</li><li><code>[!...]</code> — negated character range</li></ul><h3 id="rules-append" tabindex="-1"><code>[rules].append</code> <a class="header-anchor" href="#rules-append" aria-label="Permalink to &quot;`[rules].append`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Flags to append to the compilation command. Example: <code>[&quot;-std=c++20&quot;, &quot;-DNDEBUG&quot;]</code>.</p><h3 id="rules-remove" tabindex="-1"><code>[rules].remove</code> <a class="header-anchor" href="#rules-remove" aria-label="Permalink to &quot;`[rules].remove`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Flags to remove from the compilation command. Example: <code>[&quot;-Wall&quot;, &quot;-Werror&quot;]</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_active_file = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">compile_commands_paths = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${workspace}/build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${workspace}/cmake-build-debug&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">clang_tidy = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">append = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-std=c++23&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/test/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">append = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-DTEST_MODE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div>',65)])])}const b=t(i,[["render",s]]);export{u as __pageData,b as default};
